# pair heuristic
rows=[r for r in lab if r['family']=='spiral_classification' and r['budget']['training_steps']==256 and r['optimizer']['type']=='Adam' and r['optimizer']['lr']<=3e-5]
from collections import defaultdict
g=defaultdict(list)
for r in rows:g[r['set_id']].append(r)
wins=tot=0; ex=[]
for sid,rs in g.items():
 for a in rs:
  m=a['model']
  if m.get('residual') and m.get('depth',99)<=1 and m.get('width',0)>=192 and sum(m.get('layer_norm',[]))>=1:
   for b in rs:
    n=b['model']
    if (not n.get('residual')) and n.get('depth',0)==2 and n.get('width',0)<=192 and sum(n.get('layer_norm',[]))>=1:
     tot+=1; wins += a['mean']<b['mean']; ex.append((a['mean']<b['mean'],a['mean'],b['mean'],sid,m,n))
print('pairs',tot,'wins shallowres',wins)
for z in ex[:20]: print(z[0],round(z[1],3),round(z[2],3),z[3],z[4].get('width'),z[5].get('width'))
"}

